      if (edge()) return pick(EG);
      if (r < 0.08) return 0.0;
      if (r < 0.16) return coin(0.5) ? 1.0 : -1.0;
      if (r < 0.22) return (coin(0.5) ? 1 : -1) * rnd(1e-12, 1e-8);
      if (r < 0.27) return (coin(0.5) ? 1 : -1) * rnd(1e6, 1e9);
